import six
import functools
from .param import ParameterDefinitionBase, ParameterContainerBase, IdleValueModifier, integer


INTERNAL_VALUES_ENCODING = False


class ID(object):
    PROTO = 0
    LEGACY = 1


def get_protobuf_id(element):
    """Get protobuf ID for element."""
    proto_elem = element.find("./proto")
    if INTERNAL_VALUES_ENCODING and proto_elem is not None:
        return int(proto_elem.attrib.get('index')), ID.PROTO
    return int(element.attrib.get('id')), ID.LEGACY


def get_protobuf_type(element):
    """Get protobuf type"""
    proto_elem = element.find("./proto")
    if (proto_elem is not None) and ("type" in proto_elem.attrib):
        return str(proto_elem.attrib.get('type'))
    else:
        return None


def skip_non_numeric(func):
    """Skip non-numeric value modificaton."""
    @functools.wraps(func)
    def _wrap(inst, value):
        if not isinstance(value, (float, integer)):
            return value
        return func(inst, value)
    return _wrap


class NumericValueModifier(object):

    def __init__(self, multiplicant=None, divisor=None, shift=None):
        self.multiplicant = integer(multiplicant) if multiplicant else multiplicant
        self.divisor = float(divisor) if divisor else divisor
        self.shift = self._shift_check(shift) if shift else shift

    @skip_non_numeric
    def apply(self, value):
        """Apply parameter value modifications."""
        if self.multiplicant:
            value = integer(value) * self.multiplicant
        if self.divisor:
            value = float(value) / self.divisor
        if self.shift:
            value = integer(value) + self.shift
        return value

    @skip_non_numeric
    def revert(self, value):
        """Revert parameter value modifications."""
        if self.shift:
            value = integer(value) - self.shift
        if self.divisor:
            value = float(value) * self.divisor
        if self.multiplicant:
            value = integer(value) / self.multiplicant
        return value

    def _shift_check(self, shift):
        if isinstance(shift, (str, float)):
            return integer(float(shift))
        else:
            return integer(shift)


class SimpleTypeDefinition(object):

    def __init__(self, name):
        self.name = name

    def __str__(self):
        return "SimpleTypeDefinition ({})".format(self.name)


class EnumTypeDefinition(object):

    def __init__(self, element):
        self.name = element.attrib.get('name')
        self.enum = {}

        for enum in element.iterfind('./enum'):
            value = int(enum.attrib.get('value'))
            text = enum.attrib.get('name')
            self.enum[value] = text
            self.enum[text] = value

    def __str__(self):
        return "EnumTypeDefinition ({})".format(self.name)


class ParameterDefinition(ParameterDefinitionBase):

    def __init__(self, element):
        self.id, self.id_type = get_protobuf_id(element)
        self.protobuf_type = get_protobuf_type(element)
        self.recurrence = element.attrib.get('recurrence')
        self.type_definition = None
        super(ParameterDefinition, self).__init__(element)

    def _get_name(self, element):
        return element.attrib.get('name')

    def _get_type_name(self, element):
        return element.attrib.get('type')

    def _get_range(self, element):
        range_elem = element.find("./range")
        if range_elem is None:
            return (None, None)

        min_val = range_elem.attrib.get('min')
        if min_val is not None:
            min_val = float(min_val)

        max_val = range_elem.attrib.get('max')
        if max_val is not None:
            max_val = float(max_val)

        return (min_val, max_val)

    def _get_value_modifier(self, element):
        editing_elem = element.find("./editing")
        if editing_elem is None or self.id_type == ID.LEGACY:
            return IdleValueModifier()

        multiplicant = editing_elem.attrib.get("multiplicand")
        divisor = editing_elem.attrib.get("divisor")
        shift = editing_elem.attrib.get("shift")
        return NumericValueModifier(multiplicant, divisor, shift)

    def is_array(self):
        """Check if defintion is array."""
        return self.recurrence == "repeated"

    def is_simple(self):
        """Check if defintion is simple."""
        return isinstance(self.type_definition, SimpleTypeDefinition)

    def is_enum(self):
        """Check if defintion is enum."""
        return isinstance(self.type_definition, EnumTypeDefinition)

    def is_complex(self):
        """Check if defintion is comlex."""
        return isinstance(self.type_definition, StructDefinition)

    def set_type_definition(self, type_definition):
        """Set parameter type definition."""
        self.type_definition = type_definition

    def get_type_definition(self):
        """Get parameter type definition"""
        return self.type_definition

    def __str__(self):
        array_prefix = "array of" if self.is_array else ""
        return "ParameterDefinition. {} : {} {}".format(self.name, array_prefix, self.type_name)


class StructDefinition(ParameterContainerBase):

    def __init__(self, element, types=None):
        self.name = element.attrib.get('class') or element.attrib.get('name')
        self.parameters = {}
        self.types = types.copy() if types else {}

        for enum_elem in element.iterfind('./enumeration'):
            enum = EnumTypeDefinition(enum_elem)
            self.types[enum.name] = enum

        for struct_elem in element.iterfind('./struct'):
            struct = StructDefinition(struct_elem, self.types)
            self.types[struct.name] = struct

        for param_elem in element.iterfind('./p'):
            param = ParameterDefinition(param_elem)
            if param.type_name in self.types:
                param.set_type_definition(self.types[param.type_name])
            else:
                param.set_type_definition(SimpleTypeDefinition(param.type_name))

            self.parameters[param.id] = param
            self.parameters[param.name] = param

    def __getitem__(self, param_id):
        return self.parameters[param_id]

    def __str__(self):
        return "StructDefinition ({})".format(self.name)

    def iter_parameters(self):
        """Iterate over internal parameters."""
        return six.itervalues(self.parameters)


class ActionDefinition(object):

    def __init__(self, element, types=None):
        self.id, _ = get_protobuf_id(element)
        self.name = element.attrib.get('name')
        self.type_definition = StructDefinition(element, types)

    def is_array(self):
        """Check if defintion is array."""
        return False

    def __str__(self):
        return "ActionDefinition. {}".format(self.name)


class ManagedObjectDefinition(StructDefinition):

    def __init__(self, element):
        StructDefinition.__init__(self, element)

        for action_elem in element.iterfind('./action'):
            action = ActionDefinition(action_elem, self.types)
            self.parameters[action.id] = action
            self.parameters[action.name] = action

    def __str__(self):
        return "ManagedObjectDefinition ({})".format(self.name)
